    'ว่าย':'swim','ซื้อ':'buy','รับ':'receive','เอา':'take','คิด':'think',
    'เข้าใจ':'understand','จำ':'remember','ลืม':'forget','หา':'look for','เจอ':'find/meet',
    'จริง':'really/true','สวย':'beautiful','ใหญ่':'big','เล็ก':'small','ร้อน':'hot',
    'เย็น':'cool/cold','หนาว':'cold','สนุก':'fun','เหนื่อย':'tired','หิว':'hungry',
    'ดี':'good','เร็ว':'fast','ช้า':'slow','ง่าย':'easy','ยาก':'difficult',
    'บ้าน':'house/home','ห้อง':'room','ทะเล':'sea','หาด':'beach','ทราย':'sand',
    'น้ำ':'water','เกาะ':'island','เมือง':'city','ถนน':'road','ตลาด':'market',
    'สนามบิน':'airport','วัด':'temple','ใกล้':'near','ไกล':'far',
    'ทำ':'do','พื้น':'floor','ช้อน':'spoon','ส้อม':'fork','เรือ':'boat',
    'ตา':'eye','หน้า':'face','มือ':'hand','จมูก':'nose','ผม':'hair',
    'วัน':'day','คืน':'night','เช้า':'morning','เย็น':'evening','ปี':'year',
