    'หก':'six','เจ็ด':'seven','แปด':'eight','เก้า':'nine','สิบ':'ten',
    // Romanized fallbacks
    'khráp':'[m]','kráp':'[m]','krap':'[m]','khrap':'[m]',
    'khâ':'[f]','khà':'[f]','kha':'[f]','ka':'[f]',
    'pai':'go','bpai':'go','maa':'come','yuu':'stay',
    'tîeow':'travel/visit','thîao':'travel/visit',
    'kàw':'island','gàw':'island','kòr':'island',
    'glâi':'near','glai':'near','klai':'near',
    'phǒm':'I (male)','phom':'I (male)',
    'chǎn':'I (female)','chan':'I (female)',
