// §15 — grammar scaffold, SEPARATE from the 100-word SRS bank, unlocking by stage.
// §1/§6 — INVARIANT: if an item is an SRS vocabulary target, the grammar scaffold
// must never make it productively available before that vocabulary is introduced.
// 不 is vocabulary #10 and 没 belongs to 没有 #15, so both carry requiresVocabIds
// rather than a bare count threshold. Unlock needs stage AND prerequisites.
const MANDARIN_GRAMMAR_SCAFFOLD = [
  { id:'ma',   form:'\u5417', pinyin:'ma',  meaning:'yes/no question particle', minKnown:0,  requiresVocabIds:[] },
  { id:'bu',   form:'\u4E0D', pinyin:'b\u00F9',  meaning:'negation (non-past)', minKnown:0,  requiresVocabIds:[10], vocabId:10 },
  { id:'ge',   form:'\u4E2A', pinyin:'g\u00E8',  meaning:'general classifier',  minKnown:12, requiresVocabIds:[] },
  { id:'de',   form:'\u7684', pinyin:'de',  meaning:'possessive / modifier',    minKnown:20, requiresVocabIds:[] },
  { id:'ne',   form:'\u5462', pinyin:'ne',  meaning:'and you? / follow-up',     minKnown:20, requiresVocabIds:[] },
  { id:'ba',   form:'\u5427', pinyin:'ba',  meaning:'suggestion / softener',    minKnown:30, requiresVocabIds:[] },
  { id:'le',   form:'\u4E86', pinyin:'le',  meaning:'completed / changed state',minKnown:40, requiresVocabIds:[] },
  { id:'mei',  form:'\u6CA1', pinyin:'m\u00E9i', meaning:'negation (past / \u6709)', minKnown:14, requiresVocabIds:[15] },
  { id:'guo',  form:'\u8FC7', pinyin:'guo', meaning:'experiential aspect',      minKnown:60, requiresVocabIds:[] },
  { id:'zhe',  form:'\u7740', pinyin:'zhe', meaning:'continuous aspect',        minKnown:70, requiresVocabIds:[] },
  { id:'bi',   form:'\u6BD4', pinyin:'b\u01D0',  meaning:'comparison',          minKnown:75, requiresVocabIds:[] },
]
// A grammar item unlocks only when the learner stage is reached AND every required
// vocabulary item has actually been introduced (§6).
function mandarinScaffoldFor(vocab) {
  const list = vocab || []
  const known = list.filter(w => w.status === 'known').length
  const introduced = new Set(list.filter(w => isMandarinIntroduced(w, null)).map(w => w.id))
  return MANDARIN_GRAMMAR_SCAFFOLD.filter(g =>
    known >= g.minKnown && (g.requiresVocabIds || []).every(id => introduced.has(id)))
}

// §16 — fixed conversation basics. Explicit and tiny; never silently expanded.
// \u00a72/\u00a714 \u2014 FIXED EXPRESSIONS ONLY. productiveVocabulary:false means the whole
// string is whitelisted as an unanalysed unit: its component characters never become
// productive vocabulary, never count toward known totals and never unlock grammar.
// \u597D\u7684 was REMOVED from the early inventory because it cannot be kept safely
// isolated from productive \u7684 (which is grammar-scaffold gated at 20 known).
const MANDARIN_CONVERSATION_BASICS = [
  { id:'nihao',  form:'\u4F60\u597D', pinyin:'n\u01D0 h\u01CEo', english:'hello',
    minKnown:0, type:'conversation-basic', productiveVocabulary:false,
    // \u00a73 \u2014 pronunciation is stored per expression + context, not per character
    context:'greeting' },
  { id:'en',     form:'\u55EF',       pinyin:'\u01F9g',         english:'mm / yeah',
    minKnown:0, type:'conversation-basic', productiveVocabulary:false,
    context:'acknowledgement', pronunciationNote:'acknowledgement filler; other contexts differ' },
  { id:'zaijian',form:'\u518D\u89C1', pinyin:'z\u00E0iji\u00E0n',english:'goodbye',
    minKnown:0, type:'conversation-basic', productiveVocabulary:false, context:'parting' },
]
function mandarinBasicsFor(vocab) {
  // Counts come from SRS vocabulary only \u2014 basics are excluded by construction,
  // because they never appear in the vocab array (\u00a72).
  const known = (vocab || []).filter(w => w.status === 'known').length
  return MANDARIN_CONVERSATION_BASICS.filter(b => known >= b.minKnown)
}

// ── Mandarin segmentation & pinyin (§7, §8, §9, §10, §48) ────────────────────
// Chinese has no spaces, and characters are polyphonic, so pronunciation must be
// resolved at WORD level against a lexicon — never character by character (§8).

// Multi-character lexical items that are NOT in the SRS bank but must still
// segment as single units, plus polyphonic disambiguation entries.
const MANDARIN_EXTRA_LEXICON = [
  { w:'\u4E0D\u9519', p:'b\u00FAcu\u00F2', e:'not bad / pretty good' },
  { w:'\u4E00\u4E0B', p:'y\u00EDxi\u00E0', e:'a moment / briefly' },
]
// NOTE: \u597D\u5417 / \u597D\u5427 / \u53EF\u4EE5\u5417 are deliberately NOT lexical units. They are a content
// word plus a grammar particle, so segmentation must split them (\u00a710) \u2014 otherwise a
// target such as \u597D is hidden inside \u597D\u5417 and reported as absent (\u00a721).
// §8/§46 — polyphonic characters: the reading depends on the WORD it appears in.
// \u00a73 \u2014 pronunciation is resolved at EXPRESSION + CONTEXT level. \u55EF is not given a
// universal character reading; each contextual use is stored explicitly.
const MANDARIN_CONTEXTUAL_READINGS = {
  '\u55EF': [
    { context:'acknowledgement', pinyin:'\u01F9g', note:'agreeing / listening filler' },
    { context:'question',        pinyin:'\u0144g', note:'querying \u201chm?\u201d' },
    { context:'doubt',           pinyin:'\u01CEng', note:'surprised / doubtful' },
  ],
}
function mandarinReadingInContext(expression, context) {
  const list = MANDARIN_CONTEXTUAL_READINGS[expression]
  if (!list) return null
  const hit = list.find(x => x.context === context)
  return (hit || list[0]).pinyin
}
const MANDARIN_POLYPHONIC = {
  '\u884C': { def:'x\u00EDng', words:{ '\u94F6\u884C':'h\u00E1ng', '\u884C\u4E1A':'h\u00E1ng' } },   // xíng / háng
  '\u4E50': { def:'l\u00E8',   words:{ '\u97F3\u4E50':'yu\u00E8' } },                                 // lè / yuè
  '\u8FD8': { def:'h\u00E1i', words:{ '\u8FD8\u94B1':'hu\u00E1n', '\u5F52\u8FD8':'hu\u00E1n' } },     // hái / huán
  '\u5F97': { def:'d\u00E9',   words:{ '\u89C9\u5F97':'de', '\u8BB0\u5F97':'de', '\u5F97\u5230':'d\u00E9' } },
  '\u957F': { def:'ch\u00E1ng', words:{ '\u957F\u5927':'zh\u01CEng' } },                              // cháng / zhǎng
  '\u4E50\u610F': { def:'l\u00E8' },
}

// Builds the segmentation lexicon for a learner: bank + scaffold + basics + extras.
// Longest-match-first so \u4ECA\u5929 never splits into \u4ECA + \u5929 (\u00a710/\u00a749).
function mandarinLexicon(vocab) {
  const lex = []
  ;(vocab || RAW_MANDARIN_VOCAB).forEach(w => {
    const zh = w.chinese || w.w
    if (zh) lex.push({ w:zh, p:w.pinyin || '', e:w.english || '', type:'vocab', vocabId:w.id })
  })
  MANDARIN_GRAMMAR_SCAFFOLD.forEach(g => lex.push({ w:g.form, p:g.pinyin, e:g.meaning, type:'grammar', scaffoldId:g.id }))
  MANDARIN_CONVERSATION_BASICS.forEach(b => lex.push({ w:b.form, p:b.pinyin, e:b.english, type:'basic', basicId:b.id }))
  MANDARIN_EXTRA_LEXICON.forEach(x => lex.push({ w:x.w, p:x.p, e:x.e, type:'lexical' }))
  return lex.filter(x => x.w).sort((a, b) => b.w.length - a.w.length)
}

const ZH_PUNCT = /[\uFF0C\u3002\uFF1F\uFF01\uFF1B\uFF1A\u3001\u201C\u201D\u2018\u2019\uFF08\uFF09\s]/

// §10 — word-level segmentation. Returns segments that reconstruct the sentence
// exactly apart from punctuation/spacing.
function segmentMandarin(sentence, lexicon) {
  const s = String(sentence || '')
  const lex = lexicon || mandarinLexicon(null)
  const out = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ZH_PUNCT.test(ch)) { out.push({ surface:ch, pinyin:'', english:'', type:'punct' }); i += 1; continue }
    const hit = lex.find(x => s.startsWith(x.w, i))
    if (hit) {
      out.push({ surface:hit.w, pinyin:hit.p, english:hit.e, type:hit.type,
                 vocabId:hit.vocabId, scaffoldId:hit.scaffoldId, basicId:hit.basicId })
      i += hit.w.length; continue
    }
    // v671 §B4 — an UNTAUGHT compound (下午, 周末, 公园 …) stays ONE word, so closed-vocabulary checks, repairs and logs
    // name the word, not its characters (下 / 午)
    const comp = ZH_COMMON_COMPOUNDS.find(w => s.startsWith(w, i))
    if (comp) { out.push({ surface: comp, pinyin: '', english: '', type: 'unknown' }); i += comp.length; continue }
    // v681: a taught structure particle (们 / 地 / 得 / 着) has a fixed reading and gloss — it used to stay pinyin '' and the
    // fallback's sentence pinyin silently dropped it (live v681: 我们回家吧 → "wǒ huí jiā ba")
    if (typeof ZH_STRUCTURE_GLOSS !== 'undefined' && ZH_STRUCTURE_GLOSS[ch]) { out.push({ surface: ch, pinyin: ZH_STRUCTURE_GLOSS[ch].p, english: ZH_STRUCTURE_GLOSS[ch].e, type: 'grammar' }); i += 1; continue }
    // §8 — unknown character: record it, resolving a polyphonic default if known.
    const poly = MANDARIN_POLYPHONIC[ch]
    out.push({ surface:ch, pinyin: poly ? poly.def : '', english:'', type:'unknown' })
    i += 1
  }
  return out
}
// common two/three-character words a beginner sentence reaches for (only used to keep an UNKNOWN word whole)
const ZH_COMMON_COMPOUNDS = ('下午 上午 中午 晚上 早上 今天 明天 昨天 周末 星期 时间 时候 现在 以后 以前 公园 学校 商店 超市 饭店 餐厅 医院 银行 车站 机场 地铁 公司 ' +
  '朋友 老师 学生 医生 家人 妈妈 爸爸 哥哥 姐姐 弟弟 妹妹 东西 衣服 电影 音乐 手机 电话 电脑 咖啡 米饭 面条 水果 苹果 天气 工作 学习 休息 运动 ' +
  '喜欢 觉得 知道 认识 可以 应该 需要 开始 结束 准备 打算 一起 一点 有点 非常 已经 还是 或者 因为 所以 但是 如果 怎么 为什么 什么 多少 哪里 哪儿').split(' ').sort((a, b) => b.length - a.length)

// §8/§46 — contextual reading: a character inside a known word takes that word's
// reading, not a per-character dictionary default.
function mandarinContextualReading(word, lexicon) {
  const lex = lexicon || mandarinLexicon(null)
  const hit = lex.find(x => x.w === word)
  if (hit && hit.p) return hit.p
  for (const [ch, info] of Object.entries(MANDARIN_POLYPHONIC)) {
    if (info.words && info.words[word]) return info.words[word]
  }
  return ''
}

// §7 — pinyin validation. Tone MARKS are required for learner-facing display;
// tone-number pinyin is rejected as a display form.
// Includes \u01F9/\u0144/\u01F8 for syllabic-nasal interjections such as \u55EF, which are real pinyin.
const PINYIN_TONE_MARKS = '\u0101\u00E1\u01CE\u00E0\u0113\u00E9\u011B\u00E8\u012B\u00ED\u01D0\u00EC\u014D\u00F3\u01D2\u00F2\u016B\u00FA\u01D4\u00F9\u01D6\u01D8\u01DA\u01DC\u00FC\u01F9\u0144\u01F8\u0148\u01CE'
function isToneNumberPinyin(p) { return /[a-z\u00FC]+[1-5]\b/i.test(String(p || '')) }
function validateMandarinPinyin(p) {
  const s = String(p || '').trim()
  if (!s) return { ok:false, reason:'missing pinyin' }
  if (/[\u4E00-\u9FFF]/.test(s)) return { ok:false, reason:'pinyin contains Chinese characters' }
  if (/[\u0E00-\u0E7F]/.test(s)) return { ok:false, reason:'Thai script in pinyin' }
  if (/[\u3040-\u30FF]/.test(s)) return { ok:false, reason:'Japanese kana in pinyin' }
  if (isToneNumberPinyin(s)) return { ok:false, reason:'tone-number pinyin \u2014 tone marks required' }
  // Pinyin lines legitimately carry the sentence's own punctuation, including CJK
  // full-width marks (\u3002\uFF0C\uFF1B\uFF1A\u3001\u2026), and \u01F9/\u0144 for \u55EF-type interjections.
  const stripped = s.replace(new RegExp('[' + PINYIN_TONE_MARKS + ']', 'g'), 'a')
  if (!/^[a-zA-Z\u00FC' \-,.?!\u3002\uFF0C\uFF1B\uFF1A\u3001\uFF1F\uFF01\u2026\u201C\u201D\u2018\u2019()\uFF08\uFF09]*$/.test(stripped)) {
    const bad = [...stripped].filter(ch => !/[a-zA-Z\u00FC' \-,.?!\u3002\uFF0C\uFF1B\uFF1A\u3001\uFF1F\uFF01\u2026\u201C\u201D\u2018\u2019()\uFF08\uFF09]/.test(ch))
    return { ok:false, reason:'invalid characters in pinyin: ' + [...new Set(bad)].join(' ') }
  }
  return { ok:true }
}

// §9/§48 — tone sandhi produces SPOKEN pinyin. Canonical vocabulary pinyin is never
// overwritten; the surface form is stored separately as spokenPinyin.
const TONE3 = new RegExp('[\u01CE\u011B\u01D0\u01D2\u01D4\u01DA]')
function toneOf(syl) {
  if (/[\u0101\u0113\u012B\u014D\u016B\u01D6]/.test(syl)) return 1
  if (/[\u00E1\u00E9\u00ED\u00F3\u00FA\u01D8]/.test(syl)) return 2
  if (TONE3.test(syl)) return 3
  if (/[\u00E0\u00E8\u00EC\u00F2\u00F9\u01DC]/.test(syl)) return 4
  return 0
}
const T3_TO_T2 = { '\u01CE':'\u00E1', '\u011B':'\u00E9', '\u01D0':'\u00ED', '\u01D2':'\u00F3', '\u01D4':'\u00FA', '\u01DA':'\u01D8' }
