            onLog && onLog('  🔀 APPLICATION_SWITCH ' + target.chinese + ' recall ' + recallIndex + ': "' + String(last).slice(0, 48) + '" twice — now: ' + tpUseFor(plan, recallIndex).text.slice(0, 90))
