// ══ v648 GEMINI CLIENT — the ONLY model transport in this app ══════════════════
// Every AI request (Thai / Japanese / Mandarin generation, QC, recovery, romanisation,
// segmentation, gloss, listening, Kru chat, word auto-fill) goes through geminiRequest.
// Prompt builders stay task-specific; only the transport is unified here.
//   • model policy: Flash-Lite by default. A stage may name a Gemini model explicitly
//     (GEMINI_STAGE_MODELS); a failed request is NEVER promoted to another model.
//   • retry policy: transient overload (429 rate-limit / 500 / 503 / 504, network error,
//     timeout) → bounded retries on the SAME model (GEMINI_MAX_ATTEMPTS in total), then a
//     controlled failure. Deterministic failures (400 key / 401 / 402 / 403 / quota) fail
//     fast and latch for the rest of the run. 404 (unknown model) fails immediately.
//   • one optional second Gemini key (Settings → "Backup Gemini key"): used for the
//     retry attempts only, same model. It is a key, not a provider or model switch.
//   • telemetry: one ledger row per HTTP attempt (stage, model, attempt, tokens, HTTP,
//     cost) — the v647 cost audit, unchanged.
const GEMINI_DEFAULT_MODEL = 'gemini-2.5-flash-lite'
// Explicit, reviewed per-stage exceptions. Nothing else may choose a different model.
const GEMINI_STAGE_MODELS = {}   // v650 §9: normal track creation = Flash-Lite only (no stage override, no escalation)
const GEMINI_MAX_ATTEMPTS = 3                 // 1 request + at most 2 same-model retries
const GEMINI_RETRY_BACKOFF_MS = [2000, 4000]
const GEMINI_TIMEOUT_MS = 50000
const GEMINI_API_BASE = 'https://generativelanguage.googleapis.com/v1beta/models/'
function isGeminiApiKey(key) { const k = String(key || '').trim(); return k.length > 10 && !/^sk-/.test(k) && !/\s/.test(k) }
// Normalises any stored / legacy model string to a Gemini model id. Anything that is not
// a Gemini id (e.g. a model string persisted by an older build) becomes the default.
function geminiModelId(model) {
  const m = String(model || '').trim().replace(/^google\//, '').replace(/:.*$/, '')
  return /^gemini-[a-z0-9.\-]+$/.test(m) ? m : GEMINI_DEFAULT_MODEL
}
function geminiRetryable(status, message) {
  if (status === 500 || status === 503 || status === 504) return true
  if (status === 429 && !aiFatalProviderError(status, message)) return true
  return false
}
function geminiBackupKey() { try { return (typeof window !== 'undefined' && window.__geminiBackupKey) || '' } catch (e) { return '' } }

// v649 — request fingerprint: run (track) · stage · model · output cap · temperature ·
// schema · attempt tag · normalised prompt. An identical request that is already in
// flight, or that already SUCCEEDED in this run, is answered from that result instead of
// a second paid call. A deliberate retry carries a different attempt tag, so it is sent.
function aiRequestFingerprint(o) {
  const norm = String(o.prompt || '').replace(/\s+/g, ' ').trim()
  return aiHash([o.runId || 'norun', o.stage || '-', o.model, o.maxTokens || 0, o.temperature != null ? o.temperature : '-', o.schemaKey || '-', o.attempt || '-', norm].join('\u0001')) + ':' + norm.length
}
// Structured output (v649): judge stages ask Gemini for application/json with a schema, so
// a reply can no longer arrive as prose, a numbered list or a truncated note.
const GEMINI_SCHEMAS = {
  // v682 — the group judge's verdict in structured mode (its free-text reply was unreadable twice in the live v681+ Mandarin run)
  groupVerdict: { type: 'OBJECT', properties: { action: { type: 'STRING', enum: ['clean', 'fix_pronunciation', 'improve', 'replace'] }, reason: { type: 'STRING' }, problems: { type: 'ARRAY', items: { type: 'INTEGER' }, nullable: true } }, required: ['action'] },
  verdicts: { type: 'ARRAY', items: { type: 'OBJECT', properties: { i: { type: 'INTEGER' }, s: { type: 'INTEGER' }, note: { type: 'STRING' }, wrongSense: { type: 'BOOLEAN', nullable: true }, thaiEnglishMatch: { type: 'BOOLEAN', nullable: true }, cueRepair: { type: 'STRING', nullable: true }, issue: { type: 'STRING', nullable: true } }, required: ['i', 's'] } },
  scene: { type: 'OBJECT', properties: { A: { type: 'INTEGER' }, B: { type: 'INTEGER' }, C: { type: 'INTEGER' }, D: { type: 'INTEGER' }, E: { type: 'INTEGER' },
    brokenAtPair: { type: 'INTEGER', nullable: true }, reason: { type: 'STRING' } }, required: ['A', 'B', 'C', 'D', 'E'] },
  coherence: { type: 'OBJECT', properties: { scenes: { type: 'ARRAY', items: { type: 'OBJECT', properties: { scene: { type: 'INTEGER' }, pass: { type: 'BOOLEAN' },
    breakAfterLine: { type: 'INTEGER', nullable: true }, reason: { type: 'STRING' } }, required: ['scene', 'pass'] } }, overall: { type: 'INTEGER' }, reason: { type: 'STRING' } }, required: ['scenes'] },
  segmentation: { type: 'ARRAY', items: { type: 'OBJECT', properties: { id: { type: 'INTEGER' }, words: { type: 'ARRAY', items: { type: 'OBJECT',
    properties: { p: { type: 'STRING' }, e: { type: 'STRING' }, ph: { type: 'STRING' } }, required: ['p', 'e'] } } }, required: ['id', 'words'] } },
  lines: { type: 'ARRAY', items: { type: 'OBJECT', properties: { speaker: { type: 'STRING' }, thai: { type: 'STRING' }, english: { type: 'STRING' }, prompt: { type: 'STRING' } }, required: ['speaker', 'thai', 'english', 'prompt'] } },
  // v657 §9 — a recovery candidate DECLARES which target it realises; the app then verifies it independently
  recoveryLines: { type: 'ARRAY', items: { type: 'OBJECT', properties: { targetId: { type: 'INTEGER' }, targetSurfaceUsed: { type: 'STRING' }, speaker: { type: 'STRING' }, thai: { type: 'STRING' }, english: { type: 'STRING' }, prompt: { type: 'STRING' } }, required: ['targetSurfaceUsed', 'speaker', 'thai', 'english', 'prompt'] } },
}
