  const _promptText = (messages || []).map(m => typeof m.content === 'string' ? m.content : JSON.stringify(m.content)).join('\n')
  const modelId = geminiModelId(model)   // no promotion: the model asked for is the model sent, every attempt
  const key = String(apiKey || '').trim()
  // the run this request belongs to (captured now: a later run must not adopt it)
  const runCtl = AI_CTX.controller, runId = AI_CTX.runId
  // optional AI model (owner, v687): a run bound to Claude Haiku sends EVERY request to Anthropic — writing, quality checks,
  // pronunciation, segmentation, gloss. Never a silent switch: an Anthropic failure is reported, never retried on Gemini.
  const _aiModel = aiModelForRequest(runId, stage)
