// Settings → "Test connection": ONE tiny request through the server function (costs a fraction of a cent).
async function anthropicTestConnection() {
  const runId = aiBeginRun('haiku-connection-test')
  AI_RUN_GEN_MODEL.set(runId, 'claude-haiku-5-5')
  const text = await anthropicRequest({ model: 'claude-haiku-5-5', messages: [{ role: 'user', content: 'Reply with the single word OK.' }], maxTokens: 300, stage: 'Z_haiku_test',
    _chain: ['anthropicTestConnection'], _promptText: 'Reply with the single word OK.', runCtl: AI_CTX.controller, runId })
  const row = AI_LEDGER.filter(r => r.runId === runId).slice(-1)[0] || {}
  return { text: String(text || '').trim().slice(0, 40), model: row.servedModel || null, costUsd: row.costUsd || 0 }
}

// v688: the saved AI choice and site access code are loaded as soon as the app starts, whichever language it opens in (the
// Japanese and Mandarin screens have their own start-up, which never loaded them — their tracks silently stayed on Gemini).
;(async () => {
  try { const p = await stGet(AI_GEN_PREF_KEY); if (p) aiSetGenerationPreference(p) } catch (e) {}
  try { const c = await stGet(AI_ANTHROPIC_ACCESS_KEY); if (c) aiSetAnthropicAccess(c) } catch (e) {}
})()

// Oct13: provider names come from what the run actually used. A track made with the optional model was exported as "Generated by: Gemini ·
// model=gemini-2.5-flash-lite" (track.model is the legacy Gemini default) and its usage block was headed "GEMINI / AI USAGE".
function aiProviderName(p) { return p === 'anthropic' ? 'Claude Haiku' : p === 'gemini' ? 'Gemini' : String(p || 'AI') }
function aiProvidersUsed(sum) {
  const bp = (sum && sum.byProvider) || {}
  const used = Object.values(bp).filter(b => b && b.requests > 0).map(b => b.provider)
  if (used.length) return used
  const gm = sum && sum.generationModel
  return [gm && AI_GEN_MODELS[gm] ? AI_GEN_MODELS[gm].provider : 'gemini']
}
function trackGeneratedByLine(track) {
  const model = (track && (track.generationModel || track.model)) || GEMINI_DEFAULT_MODEL
  const prov = AI_GEN_MODELS[model] ? AI_GEN_MODELS[model].provider : 'gemini'
  const used = track && track.aiUsage ? aiProvidersUsed(track.aiUsage) : [prov]
  return 'Generated by: ' + used.map(aiProviderName).join(' + ') + ' · model=' + model
}

// ══ v675 (Step 0) — OPT-IN BENCHMARK CAPTURE (browser console only; no UI, no effect unless started) ══════════════
// window.ttBenchmark.startRecording('label') wraps window.fetch for Gemini requests ONLY while recording: the request
// body and the provider's JSON reply are copied (the app receives the untouched original response); the API key in the
// URL is redacted. stopRecording() restores the original fetch. downloadCassette() saves a tt-cassette/1 file (the same
// format the Node benchmark replays). exportLearnerSnapshot() downloads a READ-ONLY copy of the learner's per-word SRS
// state (ids, status, dates, counts — no dictionary content) for the benchmark fixtures. Nothing here writes storage.
const TT_BENCH = { recording: false, label: null, startedAt: null, entries: [], realFetch: null, ledger0: 0 }
function _ttBenchKeyless(url) { return String(url).replace(/([?&]key=)[^&]+/, '$1<redacted>') }
function ttBenchStartRecording(label) {
  if (typeof window === 'undefined' || TT_BENCH.recording) return ttBenchStatus()
  TT_BENCH.recording = true; TT_BENCH.label = label || null; TT_BENCH.startedAt = new Date().toISOString(); TT_BENCH.entries = []
  TT_BENCH.ledger0 = typeof AI_LEDGER !== 'undefined' ? AI_LEDGER.length : 0
  const real = TT_BENCH.realFetch = window.fetch
  window.fetch = async (url, opts) => {
    const res = await real(url, opts)
    if (TT_BENCH.recording && /generativelanguage\.googleapis\.com/.test(String(url))) {
      try {
        const body = await res.clone().json()
        TT_BENCH.entries.push({ seq: TT_BENCH.entries.length + 1, model: (String(url).match(/models\/([^:?]+):/) || [])[1] || null, url: _ttBenchKeyless(url),
          request: JSON.parse((opts && opts.body) || 'null'), response: { status: res.status, body } })
      } catch (e) {}
    }
    return res
  }
  return ttBenchStatus()
}
function ttBenchStopRecording() {
  if (typeof window !== 'undefined' && TT_BENCH.recording && TT_BENCH.realFetch) window.fetch = TT_BENCH.realFetch
  TT_BENCH.recording = false
  return ttBenchStatus()
}
function ttBenchStatus() { return { recording: TT_BENCH.recording, label: TT_BENCH.label, startedAt: TT_BENCH.startedAt, captured: TT_BENCH.entries.length } }
function ttBenchCassette() {
  const rows = typeof AI_LEDGER !== 'undefined' ? AI_LEDGER.slice(TT_BENCH.ledger0) : []
  return { format: 'tt-cassette/1', meta: { label: TT_BENCH.label, provider: 'LIVE gemini (browser capture)', appBuild: APP_BUILD_VERSION, model: GEMINI_DEFAULT_MODEL,
    recordedAt: TT_BENCH.startedAt, entries: TT_BENCH.entries.length, replayable: 'record only — a browser run uses the real clock, so it is an exact record of a live run, not a byte-replayable fixture' },
    entries: TT_BENCH.entries, aiCalls: aiCompactRows(rows) }
}
function _ttBenchDownload(obj, name) {
  const blob = new Blob([JSON.stringify(obj)], { type: 'application/json' })
  const url = URL.createObjectURL(blob), a = document.createElement('a')
  a.href = url; a.download = name; a.click(); URL.revokeObjectURL(url)
}
function ttBenchDownloadCassette() { _ttBenchDownload(ttBenchCassette(), 'tt-cassette-' + new Date().toISOString().slice(0, 19).replace(/:/g, '-') + '.json'); return ttBenchStatus() }
async function ttBenchLearnerSnapshot() {
  const pick = w => ({ id: w.id, surface: w.thai || w.japanese || w.chinese || null, status: w.status, interval: w.interval, repCount: w.repCount, okStreak: w.okStreak,
    lapses: w.lapses, lastSeen: w.lastSeen, dueDate: w.dueDate, introducedAt: w.introducedAt || w.introducedDate || null, manualKnown: !!w.manualKnown, difficulty: w.difficulty || null })
  const out = { format: 'tt-learner-snapshot/1', exportedAt: new Date().toISOString(), appBuild: APP_BUILD_VERSION, languages: {} }
  for (const [lang, key] of [['th', 'tt-vocab'], ['ja', JA.vocab], ['zh', ZH.vocab]]) {
    const v = await stGet(key)
    if (Array.isArray(v)) { let belt = null; try { belt = currentLearnerBelt(v) } catch (e) {}
      out.languages[lang] = { storageKey: key, words: v.length, belt, state: v.map(pick) } }
  }
  return out
}
async function ttBenchExportLearnerSnapshot() { const s = await ttBenchLearnerSnapshot(); _ttBenchDownload(s, 'tt-learner-snapshot-' + new Date().toISOString().slice(0, 10) + '.json'); return { languages: Object.keys(s.languages) } }
try { if (typeof window !== 'undefined') window.ttBenchmark = { startRecording: ttBenchStartRecording, stopRecording: ttBenchStopRecording, status: ttBenchStatus,
  downloadCassette: ttBenchDownloadCassette, cassette: ttBenchCassette, exportLearnerSnapshot: ttBenchExportLearnerSnapshot, learnerSnapshot: ttBenchLearnerSnapshot } } catch (e) {}

