    track = jaTrackObject(_tc, { pairs, scene: res.scene || scene, scenePlan: res.scenePlan || null, buildingBlocks: res.buildingBlocks || [], allowedContent: res.allowedContent || [],
      recallCount: res.recallCount, framingCount: res.framingCount, generationStats: res.generationStats || null }, targets, register, model, trackMode)
