    const o2 = await jazhQcFinaliseAndListen(track, track.language, { vocab, apiKey, model, register, runId, cancelled: () => false, onProgress: () => {}, push: m => L(m),
      onQcResult: () => {}, onFinal: t => { final = t }, onListening: () => {} })
