    const rx = new RegExp('^' + parts.map(p => V684_JA_KANJI.test(p) ? '(.+?)' : v684JaHira(p).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('') + '$')
    rds.forEach(r => { const m = r.match(rx); if (!m) return; let g = 1; parts.forEach(p => { if (V684_JA_KANJI.test(p)) add(p, m[g++]) }) })
