  if (/[぀-ヿ一-鿿]/.test(romaji)) return ['romaji contains kana or kanji']
  const N = s => String(s || '').toLowerCase().replace(/[^a-z]/g, '').replace(/ou/g, 'o').replace(/uu/g, 'u').replace(/nn/g, 'n').replace(/wa/g, 'ha').replace(/(^|[^a-z])e/g, '$1he')
