  if (lang === 'th') { THAI_TRACK_GRAMMAR_WORDS.forEach(x => items.add(x)); THAI_DISCOURSE_INTERJECTIONS.forEach(x => items.add(x)); ['ครับ', 'ค่ะ', 'คะ', 'นะ', 'ไหม', 'เหรอ', 'ล่ะ'].forEach(x => items.add(x)) }
