        ...(lang === 'ja' ? { reading: c.reading, romaji: c.romaji, phonetic: c.romaji, segments: c.segments || [] } : {}),
        ...(lang === 'zh' ? (pz => ({ pinyin: pz, phonetic: pz }))((gen2Pron('zh', c.text, st.inv) || {}).pron || '') : {}),
