    'แต่งหน้า',          // not in vocab
    'สดใส',             // not in vocab; use สวย/ใส instead
    'กว้างขวาง',        // not in vocab (target is กว้าง alone)
    'ธุรกิจ',           // not in vocab; use ร้าน/งาน/ขาย instead
