      /* legacy path below, retained for reference */
      const isTrackTarget = (ctx.currentTrackTargets || []).some(x => ((x && (x.thai || x.t)) || x) === tok)
      const direct = set.has(tok)
      // If the longest match is not allowed, try to cover the span with allowed
      // units before rejecting it: โทรหา = โทร + หา, both allowed.
      let composed = null
