const _thaiBankTurn = new Map()
// v709 (paid track 8: 68 of 90 bank lines kept, 13 of 30 exchanges then rewritten for the worse by the judges, the scene critic, quota
// recovery and the polish — ครึ่ง became "ครึ่งชิ้น" three times by one speaker) — a line whose Thai is still exactly a bank line of ITS
// word is vetted: the paid judges and the critic do not re-judge it (the deterministic checks — closed vocabulary, particles, length,
// target — still run). For the cue judge the cue must also still be the bank cue.
let _THAI_BANK_INDEX = null
const _bankNorm = x => String(x || '').replace(/\s+/g, '')
function thaiBankLineOf(p) {
  // v717 — a filled gap-fill module line is vetted too (written and blind-reviewed offline; the closed-vocabulary, particle, length, target and
  // repeat checks still run on it) — exactly as it was filled, with its cue
  if (THAI_MODULES.on && p && p.thai && THAI_MODULES.lines.size) { const ml = THAI_MODULES.lines.get(_bankNorm(p.thai)), tg0 = String(p._target || p.targetSurface || '').trim()
    if (ml && (!tg0 || ml.target === tg0)) return ml }
  if (!THAI_BANK_ON || !THAI_DAILY_EXCHANGES_ON || !p || !p.thai) return null
  // v710 (paid track 18: ได้กำไรกี่แสนคะ is in both the แสน and the กำไร exchange; the index kept only one, so under แสน the vetted line was not
  // recognised, its section was judged and the line rewritten — NOT_READY) — every exchange that holds a sentence is indexed
  if (!_THAI_BANK_INDEX) { _THAI_BANK_INDEX = new Map(); Object.entries(THAI_EXCHANGE_BANK).forEach(([t, vs]) => (vs || []).forEach(v => (v || []).forEach(l => { if (l && l.thai) { const k = _bankNorm(l.thai)
    _THAI_BANK_INDEX.set(k, (_THAI_BANK_INDEX.get(k) || []).concat([{ ...l, target: t }])) } }))) }
  const bs = _THAI_BANK_INDEX.get(_bankNorm(p.thai)); if (!bs || !bs.length) return null
  const tg = String(p._target || p.targetSurface || '').trim()
  return !tg ? bs[0] : (bs.find(b => b.target === tg) || null)
}
function thaiIsBankLine(p) { return !!(dailyV693On() && thaiBankLineOf(p)) }
function thaiBankVerdict(kind, p) {
  if (!dailyV693On()) return null
  const b = thaiBankLineOf(p); if (!b) return null
  if (kind === 'cue' && String(p.prompt || '').trim() !== String(b.prompt || '').trim()) return null
  return { s: 5, ok: true, note: 'curated bank exchange (vetted offline)', bank: true }
}
// v709 — the opening and closing lines are vetted set pieces too (blind review of paid track 7: "วันนี้ฉันดีค่ะ" sounds like "I am a
// good person"); no Thai names, so they fit any pair of characters; the cue names them. Picked by the track's first target id.
const THAI_BANK_FRAMING = [
  { opening: ['สวัสดีครับ สบายดีไหมครับ', 'Hello, how are you?', 'Greet {B} and ask how she is.'], reply: ['สวัสดีค่ะ สบายดีค่ะ', "Hello, I'm fine.", "Greet {A} back and say you're fine."],
    closing: ['ไว้เจอกันใหม่นะครับ', 'See you again.', 'Tell {B} you will see her again.'], closing_reply: ['ค่ะ แล้วเจอกันค่ะ', 'Okay, see you.', 'Say okay, see you.'] },
  { opening: ['สวัสดีครับ วันนี้เป็นยังไงบ้างครับ', 'Hello, how is your day?', 'Greet {B} and ask how her day is.'], reply: ['สวัสดีค่ะ วันนี้ก็ดีค่ะ', 'Hello, today is good.', 'Greet {A} back and say today is good.'],
    closing: ['แล้วคุยกันใหม่นะครับ', "Let's talk again.", 'Tell {B} you will talk again.'], closing_reply: ['ได้ค่ะ ดูแลตัวเองด้วยนะคะ', 'Sure, take care of yourself.', 'Say sure, and tell him to take care of himself.'] },
  { opening: ['สวัสดีครับ ไม่ได้เจอกันนานเลยนะครับ', "Hello, it's been a long time.", "Greet {B} and say it's been a long time."], reply: ['สวัสดีค่ะ นานมากเลยค่ะ', 'Hello, it really has been a long time.', 'Greet {A} back and say it really has been a long time.'],
    closing: ['งั้นผมไปก่อนนะครับ', "Well, I'll be going now.", "Tell {B} you'll be going now."], closing_reply: ['ค่ะ เดินทางปลอดภัยนะคะ', 'Okay, have a safe trip.', 'Say okay, and wish him a safe trip.'] },
]
// v715 — what the set-piece framing did besides the set pieces: the setting sentence (a set of separate exchanges) and Latin names
function thaiBankFramingScene(sd) {
  if (!sd) return sd
  return { ...sd, scene: 'Two friends chatting about everyday things — a set of short, separate exchanges, each on its own topic.' }
}
function thaiBankFraming(sd, targets) {
  // v713 — the four greeting / goodbye set pieces are app framing, not per-word vetted content: they stay on when the exchange bank is
  // switched off (D3 / D4, bank off: the model's own reply was "ฉันดีมาก" — "I am a very good person" — in both blind reviews)
  if (!dailyV693On() || !sd) return sd
  // v710 (blind review of paid track 13: "Greet นิดา …", "tell สมชาย (Somchai) …") — the English cue names a character in Latin script: a
  // character given as "นิดา (Nida)" is cued as Nida (the Thai name is kept only when no Latin form is given)
  const latin = (c, d) => { const head = String(c || d).split(',')[0], par = (head.match(/\(([^)]*)\)/) || [])[1], bare = head.replace(/\s*\([^)]*\)/g, '').trim()
    return /[\u0E00-\u0E7F]/.test(bare) && par && !/[\u0E00-\u0E7F]/.test(par) ? par.trim() : bare }
  const nA = latin(sd.characterA, 'Somchai'), nB = latin(sd.characterB, 'Nida')
  const k = Math.abs(Number((targets && targets[0] && targets[0].id) || 0)) % THAI_BANK_FRAMING.length, f = THAI_BANK_FRAMING[k], out = { ...sd, _bankFraming: k }
  // v710 (owner's review of the live v709 track: "medicine upstairs" while "at a café" — whole-track coherence 4.5/10) — the lesson is a set
  // of separate everyday exchanges, not one café conversation: the setting says so (no single place to contradict)
  out.scene = 'Two friends chatting about everyday things — a set of short, separate exchanges, each on its own topic.'
  ;['opening', 'reply', 'closing', 'closing_reply'].forEach(key => { const [th, en, cue] = f[key]
    out[key] = th; out[key + '_english'] = en; out[key + '_prompt'] = cue.replace(/\{A\}/g, nA).replace(/\{B\}/g, nB); out[key + '_phonetic'] = '' })
  return out
}
function thaiBankExchange(target) {
  if (!THAI_BANK_ON || !THAI_DAILY_EXCHANGES_ON || !dailyV693On()) return null
  const t = String((target && (target.thai || target.t)) || '').trim(), vs = THAI_EXCHANGE_BANK[t]
  if (!t || !Array.isArray(vs) || !vs.length) return null
  const k = _thaiBankTurn.get(t) || 0; _thaiBankTurn.set(t, k + 1)       // a word seen again gets its next variant
  const v = vs[k % vs.length]
  return Array.isArray(v) && v.length === 3 ? v.map(l => ({ speaker: l.speaker, thai: l.thai, english: l.english, prompt: l.prompt })) : null
}
// ══ v717 — GAP-FILL EXCHANGE MODULES (owner's thai-modules set, 25 Oct) ══════════════════════════════════════════════════════════════
// A module is a three-line A (man) → B (woman) → A exchange written ONCE with a slot for the word ({W}, {CLF}; English {E} {Es} {a}),
// usable for every word of the right type. 6,115 modules cover 2,829 of the 2,860 tagged words; each word has a type (group / subgroup)
// and a tier (T1 White/Orange … T5 Brown+). For a Daily target the writer takes a module of the word's subgroup whose tier is between the
// word's own tier and the learner's tier (never below the word's), skips the module's excluded words and modules already used in this
// lesson, fills the slots, and checks the filled Thai against the learner's closed vocabulary BEFORE it is offered. The filled exchange is
// the first candidate of the word's check ladder (no paid call) and goes through the same deterministic checks as a model reply; a word
// with no usable module (the 31 skipped words, a thin group, nothing in the learner's vocabulary) is written by the model as before.
// Source files: dev/thai-modules/ · rebuild the data below with `python3 tools/build_thai_modules.py`.
const THAI_MODULES = { on: true, ver: 'm1', data: null, loading: null, used: new Set(), cand: new Map(), lines: new Map(), rand: Math.random, stats: { offered: 0, noModule: 0, noVocab: 0 } }
const THAI_MODULE_ATTEMPTS = 6          // module candidates tried (no paid call each) before the model writes the exchange
const THAI_MODULE_POOL = 80             // candidates rendered and pre-checked per word (the first THAI_MODULE_ATTEMPTS that pass are kept)
const THAI_MODULE_TIER_OF_BELT = Object.freeze({ 'White': 1, 'Orange': 1, 'Orange + Stripe': 2, 'Blue': 2, 'Blue + Stripe': 2, 'Yellow': 3, 'Yellow + Stripe': 3,
  'Green': 4, 'Green + Stripe': 4, 'Brown': 5, 'Brown + Stripe': 5 })
function thaiModulesSetEnabled(on) { THAI_MODULES.on = !!on; THAI_MODULES.cand.clear() }
// index the embedded data (an object {t: tags by id, m: module rows}) — also the entry point for tests and the Node runner
function thaiModulesUseData(d) {
  const byGroup = new Map()
  ;(d.m || []).forEach(r => { const o = { id: r[0], group: r[1], tier: r[2], excl: r[3] ? new Set(String(r[3]).split(';').filter(Boolean)) : null, lines: [[r[4], r[5], r[6]], [r[7], r[8], r[9]], [r[10], r[11], r[12]]] }
    if (!byGroup.has(o.group)) byGroup.set(o.group, []); byGroup.get(o.group).push(o) })
  THAI_MODULES.data = { ver: d.v, tags: d.t || {}, byGroup, count: (d.m || []).length }
  THAI_MODULES.cand.clear()
  return THAI_MODULES.data.count
}
// the browser unpacks the embedded gzip once; a browser without DecompressionStream simply keeps writing with the model
async function thaiModulesLoad(log) {
  if (!THAI_MODULES.on) return null
  if (THAI_MODULES.data) return THAI_MODULES.data
  if (!THAI_MODULES.loading) THAI_MODULES.loading = (async () => {
    try {
      if (typeof DecompressionStream === 'undefined' || typeof THAI_MODULES_GZ !== 'string' || !THAI_MODULES_GZ) throw new Error('no DecompressionStream')
      const bin = Uint8Array.from(atob(THAI_MODULES_GZ), c => c.charCodeAt(0))
      const text = await new Response(new Blob([bin]).stream().pipeThrough(new DecompressionStream('gzip'))).text()
      thaiModulesUseData(JSON.parse(text))
    } catch (e) { log && log('📦 THAI_MODULES unavailable (' + String(e && e.message || e).slice(0, 80) + ') — every word is written by the model') }
    return THAI_MODULES.data
  })()
  return THAI_MODULES.loading
}
function thaiModulesBeginRun(vocab, log) {
  THAI_MODULES.used.clear(); THAI_MODULES.cand.clear(); THAI_MODULES.lines.clear(); THAI_MODULES.stats = { offered: 0, noModule: 0, noVocab: 0 }
  const d = THAI_MODULES.data
  if (log) log(d ? '📦 THAI_MODULES ' + d.ver + ' · ' + d.count + ' gap-fill modules · learner tier T' + thaiModuleLearnerTier(vocab) + ' · a word with no module that fits the learner\'s vocabulary is written by the model'
    : '📦 THAI_MODULES not loaded — every word is written by the model')
}
function thaiModuleLearnerTier(vocab) {
  try { const b = currentLearnerBelt(vocab); return THAI_MODULE_TIER_OF_BELT[b && b.label] || 5 } catch (e) { return 5 }
}
function thaiModuleTagOf(target) {
  const d = THAI_MODULES.data; if (!d || !target) return null
  const tg = d.tags[String(target.id != null ? target.id : target.wordId)]; if (!tg) return null
  const clean = x => String(x || '').replace(/\s*(\.\.\.|…)\s*$/, '').trim()
  return clean(tg[0]) === clean(target.thai || target.t) ? { thai: clean(tg[0]), tier: tg[1], group: tg[2], second: tg[3], sub: tg[4], clf: tg[5], slot: tg[6], slot2: tg[7], plural: tg[8] } : null
}
// ← render.py: {E} {Es} {a} filled for one word; "a" / "an" by the sound of the next word; pair and mass nouns (plural == slot) take none
function thaiModuleFill(text, slot, plural) {
  const noArt = !!plural && plural === slot
  const out = String(text || '').replace(/\{Es\}/g, plural || slot).replace(/\{E\}/g, slot)
    .replace(/\{a\} (\S+)/g, (m0, w) => noArt ? w : ((/^(?:[aeiouAEIOU]|hour|honest|heir)/.test(w) && !/^(?:uni|use|usu|one|Euro|eu)/i.test(w)) ? 'an ' : 'a ') + w)
  return out.replace(/ {2,}/g, ' ').trim()
}
// every module that could suit the word: its subgroup (else its second group), tier between the word's own and the learner's, not excluded,
// not used in this lesson — best tier first (the learner's own), random within a tier
function thaiModuleCandidates(target, learnerTier) {
  const d = THAI_MODULES.data, tag = thaiModuleTagOf(target); if (!d || !tag) return []
  const id = String(target.id != null ? target.id : target.wordId), hi = Math.max(tag.tier, learnerTier || tag.tier)
  const pick = list => (list || []).filter(m => m.tier >= tag.tier && m.tier <= hi && !(m.excl && m.excl.has(id)) && !THAI_MODULES.used.has(m.id))
  let mods = pick(d.byGroup.get(tag.sub || tag.group))
  if (!mods.length && tag.second) { d.byGroup.forEach((list, g) => { if (g === tag.second || g.startsWith(tag.second + '.')) mods = mods.concat(pick(list)) }) }
  const r = new Map(mods.map(m => [m.id, THAI_MODULES.rand()]))
  mods.sort((a, b) => (b.tier - a.tier) || (r.get(a.id) - r.get(b.id)))
  return mods.map(m => ({ m, tag }))
}
function thaiModuleRender(c, target) {
  const { m, tag } = c, secondGroup = m.group.split('.')[0] === tag.second && !!tag.slot2
  const slot = secondGroup ? tag.slot2 : tag.slot, plural = secondGroup ? '' : tag.plural
  if (!slot) return null
  const hasClf = m.lines.some(l => /\{CLF\}/.test(l[0]))
  if (hasClf && !tag.clf) return null
  const sp = ['A', 'B', 'A']
  const lines = m.lines.map((l, k) => ({ speaker: sp[k], thai: String(l[0]).replace(/\{W\}/g, tag.thai).replace(/\{CLF\}/g, tag.clf), english: thaiModuleFill(l[1], slot, plural), prompt: thaiModuleFill(l[2], slot, plural), _moduleId: m.id }))
  return lines.some(l => /[{}]/.test(l.thai + l.english + l.prompt)) ? null : lines
}
// the writer's own deterministic rules, applied to a filled module BEFORE it is offered (so a module that would be refused costs no attempt):
// the quality gate (closed vocabulary, belt length, particles, cue form), one phrase repeated in every line, echoes / copies (variety), the
// lexical-sense rules, and a sentence from a recent lesson. Returns the problems (empty = the exchange can be offered).
function thaiModuleLinesProblems(lines, target, vocab) {
  const out = [], sq = x => String(x || '').replace(/\s+/g, '')
  try {
    const q = validateSmartPairs(lines.map(l => ({ speaker: l.speaker, thai: l.thai, phonetic: '', english: l.english, prompt: l.prompt || '.' })), target, vocab, false, new Set(), true)
    if (q.valid.length < lines.length) out.push(String((q.failures || [])[0] || 'quality check').slice(0, 80))
  } catch (e) { out.push('quality check error') }
  if (out.length) return out
  const tg = sq(target.thai).replace(/\.\.\.|…/g, '')
  const win = lines.map(l => { const t = sq(l.thai), i = t.indexOf(tg); if (i < 0) return null
    const after = t.slice(i + tg.length).replace(/^(ครับ|ค่ะ|คะ|นะ)+/, '').slice(0, 3), before = t.slice(Math.max(0, i - 3), i)
    return { after: after.length >= 2 ? after : null, before: before.length >= 2 && !/^(ผม|ฉัน|คุณ)$/.test(before) ? before : null } })
  const nWith = win.filter(Boolean).length, rep = k => { const v = win.map(w => w && w[k]).filter(Boolean); return nWith >= 3 && v.length === nWith && v.every(x => x === v[0]) ? v[0] : undefined }
  if (tg.length >= 2 && (rep('after') || rep('before'))) out.push('same phrase in every line')
  try { thaiExchangeVarietyProblems(lines, target.thai).forEach(x => out.push(x)) } catch (e) {}
  try { lines.forEach(l => thaiLexicalSenseProblems({ thai: l.thai, english: l.english }, target.thai).forEach(x => out.push(x.why))) } catch (e) {}
  lines.forEach(l => { if (thaiRecentRepeat(l.thai)) out.push('recent lesson repeat') })
  if (/^(งั้น|ไม่เอา|ไม่ครับ|ไม่ค่ะ|ใช่|ได้ครับ|ได้ค่ะ|แล้ว(?!ก็)|ก็)/.test(sq(lines[0].thai))) out.push('line 1 continues an earlier exchange')
  return out
}
// the next unused module exchange for a word, vocabulary-checked against THIS learner; null when there is none (the model writes it)
function thaiModuleExchange(target, vocab, log) {
  if (!THAI_MODULES.on || !THAI_MODULES.data || !dailyV693On() || !target) return null
  const key = String(target.id != null ? target.id : target.thai)
  let list = THAI_MODULES.cand.get(key)
  if (!list) {
    list = []
    const cands = thaiModuleCandidates(target, thaiModuleLearnerTier(vocab))
    let tried = 0, blocked = 0
    for (const c of cands) {
      if (list.length >= THAI_MODULE_ATTEMPTS || tried >= THAI_MODULE_POOL) break
      const lines = thaiModuleRender(c, target); if (!lines) continue
      tried++
      if (thaiModuleLinesProblems(lines, target, vocab).length) { blocked++; continue }
      list.push({ id: c.m.id, tier: c.m.tier, lines })
    }
    THAI_MODULES.cand.set(key, list)
    if (!list.length) { if (cands.length) THAI_MODULES.stats.noVocab++; else THAI_MODULES.stats.noModule++
      log && log('📦 TH_MODULE ' + (target.thai || key) + ': ' + (cands.length ? 'none of ' + Math.min(cands.length, THAI_MODULE_POOL) + ' modules passes the writer\'s checks for this learner (' + blocked + ' refused)' : 'no module for this word') + ' — written by the model') }
  }
  const c = list.shift(); if (!c) return null
  THAI_MODULES.used.add(c.id); THAI_MODULES.stats.offered++
  c.lines.forEach(l => THAI_MODULES.lines.set(_bankNorm(l.thai), { speaker: l.speaker, thai: l.thai, english: l.english, prompt: l.prompt, target: String(target.thai || target.t || ''), module: c.id }))
  log && log('📦 TH_MODULE ' + target.thai + ': module ' + c.id + ' (T' + c.tier + ') as the first candidate (no paid call)')
  return c.lines.map(l => ({ speaker: l.speaker, thai: l.thai, english: l.english, prompt: l.prompt, _moduleId: l.module || l._moduleId }))
}
// a word that has a module (not yet vocabulary-checked) needs no usage profile from the model
function thaiModuleHas(target) {
  if (!THAI_MODULES.on || !THAI_MODULES.data || !target) return false
  const tag = thaiModuleTagOf(target); return !!tag && thaiModuleCandidates(target, 5).length > 0
}
// THAI_MODULES_DATA_BEGIN
const THAI_MODULES_GZ = ""
// THAI_MODULES_DATA_END
// v715 (owner's review of the live v714 track) — three uses, not three copies, for one three-line exchange (used while the exchange is
// written, so a failing one is rewritten in full): echoes, a fixed phrase that opens two lines, two nearly identical lines
function thaiExchangeVarietyProblems(g, targetThai) {
  const out = [], sq = x => String(x || '').replace(/\s+/g, '')
  const tg2 = sq(targetThai).replace(/\.\.\.|…/g, '')
  const rest = l => sq(l.thai).replace(/(ครับ|ค่ะ|คะ|นะ|จ้ะ|จ้า)/g, '').split(tg2).join('').replace(/^(ผม|ฉัน|คุณ|เรา)/, '').replace(/(ก็|ใช่ไหม|ใช่|จริง|เหมือนกัน|ด้วย|เลย|มาก)/g, '')
  if (tg2.length >= 4 && g.filter(l => sq(l.thai).includes(tg2) && rest(l).length < 3).length >= 2)
    out.push('Two lines only repeat "' + targetThai + '" (an echo, nothing new) — each line must add something new: say it, talk about saying it, or ask when to say it')
  if (tg2.length >= 8 && g.filter(l => sq(l.thai).replace(/^(ผม|ฉัน)/, '').startsWith(tg2)).length >= 2)
    out.push('"' + targetThai + '" opens two lines — the same phrase said twice is one use, not two; use it in a different way in one line (talk about it, quote it, plan it)')
  const bg = x => { const t = sq(x).replace(/(ครับ|ค่ะ|คะ|นะ)/g, ''), b = new Set(); for (let i = 0; i < t.length - 1; i++) b.add(t.slice(i, i + 2)); return b }
  for (let i = 0; i < g.length; i++) for (let j = i + 1; j < g.length; j++) { const a = bg(g[i].thai), b = bg(g[j].thai); let n = 0; a.forEach(x => { if (b.has(x)) n++ })
    if (a.size >= 6 && b.size >= 6 && n / (a.size + b.size - n) >= 0.75) out.push('Lines ' + (i + 1) + ' and ' + (j + 1) + ' are nearly the same sentence — every line must say something new') }
  // line 2 asks, and line 3 asks much the same thing back instead of answering (owner's review, lines 90–92: ช่วยดูของให้หน่อยได้ไหม →
  // ได้ครับ ช่วยดูให้ได้ไหม)
  const isQ = x => /(ไหม|มั้ย|หรือเปล่า|หรือยัง|อะไร|ที่ไหน|ไหน|ใคร|เมื่อไหร่|ทำไม|กี่|เท่าไหร่|ยังไง|เหรอ)(ครับ|คะ|ค่ะ|นะ)?$/.test(sq(x))
  if (g.length >= 3 && isQ(g[1].thai) && isQ(g[2].thai)) { const a = bg(g[1].thai), b = bg(g[2].thai); let n = 0; a.forEach(x => { if (b.has(x)) n++ })
    if (n / (a.size + b.size - n) >= 0.5) out.push('Line 3 asks line 2\'s question back instead of answering it — line 3 answers (and may add something new)') }
  return out
}
