        g.forEach((l, li) => { const rr = thaiRecentRepeat(l.thai); if (rr) naturalFails.push('Line ' + (li + 1) + ' (' + l.thai + ') ' + (rr === 'exact' ? 'is the same sentence as' : 'is almost the same as') + ' a line in a recent lesson — write a different situation') })
