const _EVERYDAY_PRICE_CTX = /\b(restaurant|food|meal|lunch|dinner|breakfast|snack|dessert|coffee|tea|drink|noodle|rice|shirt|clothes|market|street|stall|taxi|bus|ticket|massage|fruit|squid|meat)\b/i
const _PRICE_CTX = /\b(price|prices|cost|costs|baht|expensive|cheap|pay|paid|charge)\b/i
const EVERYDAY_PRICE_CEILING_BAHT = 5000
