// Any text it returns is ignored; every index resolves back to an immutable source pair.

// Shared lifecycle: build a Listening Track from a FINAL Main Track. Never mutates it.
// Conversation first, coverage second.
async function buildListeningTrack(mainTrack, vocab, opts) {
  const o = opts || {}, lang = o.lang || 'th', log = o.onLog || null
  // v656: EVERY language, every new build → a FRESH conversation (the anchor and block paths are retired)
  return buildListeningConversation(mainTrack, vocab, { ...o, lang })
}
// Coverage label from what the Listening Track ACTUALLY teaches. Never claims "all"
// unless every track target has a designated line here.
function listeningCoverageLabel(lt, mainTrack) {
  if (!lt) return ''
  const cv = lt.coverage
  if (cv && cv.contract === 'ALL_SELECTED_TARGETS') {
    // v656 §27 — the primary denominator is the 30 selected targets; NEW / REVIEW are detail
    const surf = id => { const r = (cv.rows || []).find(x => x.targetId === id); return r ? r.target : String(id) }
    let s = 'TARGET COVERAGE ' + cv.coveredTargetIds.length + '/' + cv.selectedTargetIds.length +
      ' · NEW ' + cv.newHeardIds.length + '/' + cv.newTargetIds.length + ' · REVIEW ' + cv.reviewHeardIds.length + '/' + cv.reviewTargetIds.length
    if (cv.uncoveredTargetIds.length) s += ' · Missing: ' + cv.uncoveredTargetIds.map(surf).join(', ')
    s += lt.readiness === 'READY' ? ' · READY' + ((lt.qualityNotes || []).length ? ' · ' + lt.qualityNotes.length + ' quality note' + (lt.qualityNotes.length === 1 ? '' : 's') : '') : mainTrack && mainTrack.playable ? ' · PLAYING WITH ISSUES' : ' · LISTENING TRACK NEEDS REPAIR'
    return s
  }
  if (cv && cv.requiredTargetIds) {
    const surf = id => { const r = (cv.rows || []).find(x => x.targetId === id); return r ? r.target : String(id) }
    let s = 'REVIEW COVERAGE ' + cv.coveredRequiredIds.length + '/' + cv.requiredTargetIds.length
    if (cv.newTargetIds.length) s += ' · NEW WORDS HEARD ' + cv.newHeardIds.length + '/' + cv.newTargetIds.length
    if (cv.unresolved.length) s += ' · Unresolved: ' + cv.unresolved.map(u => u.target || surf(u.targetId)).join(', ')
    if (lt.listeningQuality) s += ' · LISTENING QUALITY ' + lt.listeningQuality
    return s
  }
  const total = (lt.coverage && lt.coverage.trackTargetCount) || ((mainTrack && mainTrack.keywords) || []).length
  const covered = new Set((lt.lines || []).filter(l => l.targetId != null && !l.supporting).map(l => l.targetId)).size
  if (!total) return ''
  return covered === total ? 'all ' + total + ' track words covered' : covered + '/' + total + ' targets covered'
}

// ══ LISTENING COVERAGE (shared helpers) ═════════════════════════════════════════════
// v656: the v640–v655 anchor pipeline is retired (see buildListeningConversation). What stays here
