  if (/^(hello|hi|good (morning|evening|night)|goodbye|bye|see you|good luck|take care|thank|sorry|excuse me)\b/.test(g))
    return ['say it at the natural moment (opening / closing / after help)', 'say it to a different person or in a different moment', 'say it as a reply to the other person']
  if (/^to\s/.test(g) || /verb/.test(pos)) return ['state what someone does or will do', 'ask the other person whether they do it', 'suggest it, ask for it, or say you will not do it']
