    (f.anchors.length ? ' — build it from these taught words: ' + f.anchors.join(' ') : '') + (f.limit ? ' — ' + f.limit : '') +
    (f.untaughtNear && f.untaughtNear.length ? ' — NOT taught (never use): ' + f.untaughtNear.join(' ') : '') + '.\n' +
    (plan.acceptedFunctions.length ? 'ALREADY ACCEPTED functions (do not repeat): ' + plan.acceptedFunctions.join(', ') + '.\n' : '') +
    (plan.rejected.length ? 'REJECTED constructions (do not repeat): ' + plan.rejected.slice(-4).map(r => (r.text ? '"' + r.text.slice(0, 40) + '"' : r.id) + ' — ' + r.reason).join(' | ') + '.\n' : '') +
    (plan.unavailable.length ? 'NOT AVAILABLE with the taught words: ' + plan.unavailable.map(u => u.id + ' (needs ' + u.missing.join('+') + ')').join(', ') + '.\n' : '')
