  if (/SPEAKER|male and female|particle/.test(t)) return 'SPEAKER_CONFLICT'
  if (/CLOSED_VOCABULARY|untaught|not taught|BLOCKED/.test(t)) return 'CLOSED_VOCABULARY'
  if (/WRONG_SENSE/.test(t)) return 'WRONG_SENSE'
  if (/CUE_MISMATCH/.test(t)) return 'CUE_MISMATCH'
