  if (LISTENING_SITUATION_SIMPLE[top] && !out.some(x => x.text === LISTENING_SITUATION_SIMPLE[top])) out.push({ text: LISTENING_SITUATION_SIMPLE[top], needs: nd(LISTENING_SITUATION_SIMPLE[top]) })
