  DECIDE: [{ text: 'they decide what to do and where to go together', needs: ['go|went|going|visit'] }, { text: 'they decide what to do next together', needs: [] }],
  ARRANGE: [{ text: 'they arrange WHEN to go and how long it will take — one time is agreed and then stays agreed', needs: ["time|o'clock|when|hour|morning", 'go|meet|leave|start'] },
    { text: 'they agree WHEN to go — one time is agreed and then stays agreed', needs: ["time|o'clock|when|hour|morning"] }, { text: 'they agree what to do first', needs: [] }],
  MOVE: [{ text: 'they set off and get there (the way, the transport) and arrive', needs: ['go|went|going', 'way|road|taxi|bus|car|walk|train'] }, { text: 'they go there and arrive', needs: ['go|went|going'] }, { text: 'they get there', needs: [] }],
  DO: [{ text: 'they do the main activity there: eat, look around or pick something', needs: ['eat|food|buy|look|see|drink'] }, { text: 'they do what they came for', needs: [] }],
  PAY: [{ text: 'they pay: the price, card or cash, the receipt', needs: ['pay|price|how much|money|baht|cost', 'card|cash|receipt'] }, { text: 'they pay and check the price', needs: ['pay|price|how much|money|baht|cost'] }, { text: 'they finish up there', needs: [] }],
