  if (/\b(\d+\s*(am|pm)|o'clock|noon|midnight|what time|when|morning|afternoon|evening|tomorrow|today|appointment|schedule|in advance)\b/.test(g)) return 'ARRANGE'
  if (/how old|age|years old|name|how are you|how is|you all|friend|family|brother|sister|mother|father/.test(g)) return 'OPEN'
  if (/\b(taxi|bus|train|car|way|road|route|walk|drive|arrive|get there|far|near|street|map)\b/.test(g)) return 'MOVE'
  if (/\b(price|cost|how much|baht|yen|yuan|money|pay|card|receipt|discount|cheap|expensive|change|cash)\b/.test(g) || d === 'shopping & payment' || d === 'big amounts' || (d === 'numbers & prices' && r === 'NUMBER')) return 'PAY'
