const LISTENING_PHASE_TIME = { OPEN: 'now — where they meet', DECIDE: 'now — still where they meet', ARRANGE: 'now — planning when to go (later today)', MOVE: 'later — on the way, after agreeing the time',
  DO: 'later — at the place they chose', PAY: 'later — at the end of the visit', CLOSE: 'at the end — as they part' }
