  if (state.unresolvedQuestions.length) {
    const q = state.unresolvedQuestions[0]
    const tag = /\b(right|isn'?t it|aren'?t you|don'?t you|won'?t you|okay|ok|yeah|huh|no)\?$/i.test(q.english)
    const qt = !tag && cand.turns[0].speaker !== q.speaker ? listeningQtypeIssue(q.english, en[0], true, /\?$/.test(en[0])) : null
    if (!tag && (cand.turns[0].speaker === q.speaker || qt)) out.push({ code: 'TRANSITION', line: 1, detail: 'the previous part ended with the question "' + q.english.slice(0, 50) + '" — the first turn must ANSWER it' + (qt ? ' (' + qt.slice(0, 60) + ')' : ' (the other speaker)') })
  }
  en.forEach((e, k) => {
    if (state.paymentsCompleted > 0 && LN_PAY_EN.test(e)) out.push({ code: 'STATE_CONFLICT', line: k + 1, detail: 'they already paid — no second payment' })
    if (state.eatingDone && LN_EAT_START_EN.test(e)) out.push({ code: 'STATE_CONFLICT', line: k + 1, detail: 'they already ate — eating does not start again' })
    const ck = LN_CLOCK_EN.exec(e)
    if (ck && state.agreedTimes.length && sp.phase !== 'ARRANGE' && !state.agreedTimes.includes(ck[0].toLowerCase()) && !/\b(instead|actually|change|rather)\b/i.test(e))
      out.push({ code: 'STATE_CONFLICT', line: k + 1, detail: 'the agreed time is ' + state.agreedTimes[state.agreedTimes.length - 1] + ' — it stays agreed (no silent change to ' + ck[0] + ')' })
  })
