    const th = String(x.thai || '').trim().replace(/นะค่ะ$/, 'นะคะ').replace(/(อุณหภูมิ[^ ]{0,8}?)(เย็น|หนาว)/, '$1ต่ำ').replace(/(อุณหภูมิ[^ ]{0,8}?)ร้อน/, '$1สูง')
