    ;(coh.verdicts || []).filter(v => !v.pass).forEach(v => { const si = v.scene - 1; if (si >= 0 && si < nS) flagged.set(si, (flagged.get(si) || []).concat([{ line: v.breakAfterLine ? Math.max(1, Number(v.breakAfterLine) - offs[si]) : 0, code: 'STORY', detail: v.reason }])) })
