function modelMarkupFound(s) {
  const str = String(s == null ? '' : s)
  return MODEL_MARKUP_PATTERNS.filter(m => { m.re.lastIndex = 0; const hit = m.re.test(str); m.re.lastIndex = 0; return hit }).map(m => m.id)
}
function stripModelMarkup(s) {
  if (s == null) return s
  let out = String(s)
  MODEL_MARKUP_PATTERNS.forEach(m => { m.re.lastIndex = 0; out = out.replace(m.re, '') })
  return out
}
