  if (/คะ(?!แนน|น้า)/.test(s)) female.push('คะ')
  if (/ดิฉัน/.test(s)) female.push('ดิฉัน')
  else if (/ฉัน/.test(s)) female.push('ฉัน')      // weak: men also say ฉัน casually
