// Cue AND English are checked; each problem names the field it was found in.
function thaiTemplateGarbageProblems(p) {
  const out = []
  ;[['cue', p && p.prompt], ['english', p && p.english]].forEach(([field, s]) => {
    const t = String(s || '')
    if (!t) return
    THAI_TEMPLATE_GARBAGE_RULES.forEach(r => { if (r.re.test(t)) out.push({ field, id: r.id, why: field + ': ' + r.why + ' — "' + t.slice(0, 70) + '"' }) })
  })
  return out
}
// Thai clock: 1–5 โมงเช้า, บ่าย N โมง, N โมงเย็น, N ทุ่ม, or N นาฬิกา (24-hour). 13–24 + โมง
