// ── Model naturalness gate ──────────────────────────────────────────────────────
// "Would a native speaker plausibly say this exact sentence in ordinary conversation,
// with this intended meaning?" Scored on the FINAL text; < 4 fails.
async function _qrBatchNaturalnessCheck(pairs, apiKey, model, onLog) {
  const eligible = pairs.map((p, i) => ({ i, p })).filter(({ p }) => p && p.thai && p.pairType !== 'framing')
  const scored = new Map()
  const BATCH = 12
  for (let b = 0; b < eligible.length; b += BATCH) {
    const chunk = eligible.slice(b, b + BATCH)
    const raw = await geminiJudge(apiKey, model, _naturalnessPromptText(chunk.map(x => x.p)), 1400)
    try {
      const parsed = JSON.parse(String(raw || '').replace(/```json|```/g, '').trim())
      parsed.forEach(({ i: ci, s, note, construction, alternative, issue }) => { const orig = chunk[ci - 1]; if (orig && s != null) scored.set(orig.i, { s: Number(s), note: note || '', construction: construction || '', alternative: alternative || '', issue: issue || null }) })
    } catch (e) { onLog && onLog('  ⚠️ naturalness batch ' + (Math.floor(b / BATCH) + 1) + ' unparseable — not judged') }
  }
  return scored
}

async function _qrBatchPromptCheck(pairs, apiKey, model, onLog) {
  // Only check pairs that have both a real prompt and Thai content
  const eligible = pairs.map((p, i) => ({ i, p })).filter(({ p }) =>
    p.prompt && p.prompt.length > 8 && p.thai && p.english &&
    !p.prompt.startsWith('.') && !/^(greet|greeting)/i.test(p.prompt) &&
    // v710 (paid track 14: the vetted อิจฉา cue "Tell her then your friends at the office will probably envy you" scored 2/5 and the group was
    // replaced) — a vetted bank line with its bank cue is not re-judged here (bank-level judging only; the final audit still checks it)
    !thaiBankVerdict('cue', p)
  )
  if (!eligible.length) return pairs

  const BATCH = 12
  const scored = new Map()

  for (let b = 0; b < eligible.length; b += BATCH) {
    const chunk = eligible.slice(b, b + BATCH)
    const batchNum = Math.floor(b/BATCH)+1
    const totalBatches = Math.ceil(eligible.length/BATCH)
    onLog?.(`  Batch ${batchNum}/${totalBatches}: checking ${chunk.length} pairs (e.g. "${(chunk[0]?.p?.prompt||'').slice(0,40)}…")`)
    const numbered = chunk.map(({ i, p }, ci) =>
      `${ci + 1}. Prompt: "${p.prompt}"\n   Thai: ${p.thai}\n   English: ${p.english}`
    ).join('\n\n')

    const raw = await geminiJudge(apiKey, model,
      `Rate how well each Thai sentence matches its prompt description.\n\nScale:\n5 = sentence perfectly expresses exactly what the prompt says (including when the meaning is identical)\n4 = very close, minor phrasing difference only\n3 = related but a key detail is missing or changed\n2 = loosely related, significant mismatch\n1 = sentence does not match the prompt\n\nCRITICAL: If the prompt and English translation convey the SAME meaning (even with different wording), score 5. Only score below 5 if there is a genuine factual or content mismatch.\n\nDIALOGUE RULE: These are conversation pairs. Prompts describe what a character says in third person ("He says he likes...", "She asks if...") but the Thai sentence naturally uses first person ("ผม/ฉัน = I"). This is CORRECT and NEVER a mismatch.${dailyV693On() ? THAI_CUE_LEARNER_YOU_RULE : ''} Score 5 when "She says she agrees" matches "I agree", or "He says he wants" matches "I want". Only penalise if the actual CONTENT or TOPIC differs.\n\n${THAI_CUE_PERSPECTIVE_RULE}\n\n${numbered}\n\nReturn ONLY JSON array: [{"i":1,"s":5},{"i":2,"s":3,"note":"prompt says X but sentence says Y"},...]\nno markdown, no explanation.`, 1200)

    try {
      const parsed = JSON.parse(raw.replace(/```json|```/g, '').trim())
      parsed.forEach(({ i: ci, s, note }) => {
        const orig = chunk[ci - 1]
        if (orig) scored.set(orig.i, { s: s || 5, note: note || '' })
      })
    } catch(e) { /* skip batch on parse fail */ }
  }

  return pairs.map((p, i) => {
    const sc = scored.get(i)
    if (!sc) return p
    return { ...p, _pm: sc.s, _pmNote: sc.note }
  })
}

// ── Thai Tone Calculator ─────────────────────────────────────────────────────
// Deterministically computes expected RTGS tone from Thai script.
// Rules: initial consonant class × tone mark × syllable type → one of 5 tones.
const _TH_HIGH  = new Set([...'ขฃฉฐถผฝศษสห'])
const _TH_MID   = new Set([...'กจดตฎฏบปอ'])
const _TH_STOP  = new Set([...'กขคฆดตถทธบปพฟภ'])  // stop finals → dead syllable
const _TH_LEAD  = new Set([...'\u0e40\u0e41\u0e42\u0e43\u0e44'])  // เ แ โ ใ ไ
const _TH_HNAM  = new Set([...'\u0e19\u0e21\u0e07\u0e27\u0e22\u0e25\u0e23\u0e2c'])  // น ม ง ว ย ล ร ฬ
const _TH_LONGV = new Set([...'\u0e32\u0e35\u0e39\u0e37'])  // า ี ู ื
const _TH_SHORTV = new Set([...'\u0e30\u0e47'])  // ะ ็
const _TH_TM = {'\u0e48':'ek','\u0e49':'tho','\u0e4a':'tri','\u0e4b':'jat'}
const _TH_CONS = c => '\u0e01' <= c && c <= '\u0e2e'

function _thCls(ch) {
  return _TH_HIGH.has(ch) ? 'high' : _TH_MID.has(ch) ? 'mid' : 'low'
}

function calcThaiSyllableTone(syl) {
  const chars = [...syl].filter(c => '\u0e00' <= c && c <= '\u0e5b')
  if (!chars.length) return null
  let i = 0

  // Skip leading vowel (เ แ โ ใ ไ)
  const hasLead = _TH_LEAD.has(chars[0])
  if (hasLead) i++
  if (i >= chars.length) return null

  // Initial consonant class — handle ห นำ
  let cls
  if (chars[i] === '\u0e2b' && _TH_HNAM.has(chars[i+1])) {
    cls = 'high'; i += 2  // ห นำ → high class
  } else {
    cls = _thCls(chars[i]); i++
  }

  // Tone mark (scan full syllable)
  let tm = null
  for (const c of chars) if (_TH_TM[c]) { tm = _TH_TM[c]; break }

  // Dead syllable: has short-vowel marker OR ends in stop final
  const shortV = chars.some(c => _TH_SHORTV.has(c))
  const allCons = chars.filter(_TH_CONS)
  const finalCons = allCons.length >= 2 ? allCons[allCons.length - 1] : null
  const stopEnd = finalCons && _TH_STOP.has(finalCons)
  const dead = shortV || stopEnd

  // Long vowel (needed to distinguish low-class dead tones)
  const longV = hasLead || chars.some(c => _TH_LONGV.has(c))

  // Tone table
  if (tm) {
    const TBL = {
      ek:  { mid:'low',     high:'low',     low:'falling' },
      tho: { mid:'falling', high:'falling', low:'high'    },
      tri: { mid:'high',    high:'high',    low:'high'    },
      jat: { mid:'rising',  high:'rising',  low:'rising'  },
    }
    return TBL[tm][cls]
  }
  if (dead) {
    if (cls === 'low') return (shortV || !longV) ? 'high' : 'falling'
    return 'low'  // mid/high class dead syllable → low
  }
  return cls === 'high' ? 'rising' : 'mid'
}

// Fix (or add) tone diacritic in an RTGS phonetic string
function fixRTGSToneMark(rtgs, expectedTone) {
  const MARK = { low:'\u0300', high:'\u0301', falling:'\u0302', rising:'\u030C', mid:'' }
  const newMark = MARK[expectedTone] ?? ''
  const nfd = rtgs.normalize('NFD')
  const DIAC = /[\u0300\u0301\u0302\u030C]/

  if (DIAC.test(nfd)) {
    // Replace existing diacritic with correct one (or remove for mid)
    return nfd.replace(DIAC, newMark).normalize('NFC')
  }
  if (!newMark) return rtgs  // mid tone — no mark, already correct

  // Add mark to first vowel letter
  const vi = nfd.search(/[aeiouAEIOU]/)
  if (vi < 0) return rtgs
  return (nfd.slice(0, vi+1) + newMark + nfd.slice(vi+1)).normalize('NFC')
}

// Split Thai word into syllables (heuristic for common patterns)
function splitThaiSyllables(thai) {
  const chars = [...thai].filter(c => '\u0e00' <= c && c <= '\u0e5b')
  const syls = []; let cur = []
  const isAbove = c => '\u0e31' <= c && c <= '\u0e4e'

  for (let i = 0; i < chars.length; i++) {
    const c = chars[i]
    if (_TH_LEAD.has(c)) {
      // Leading vowel starts a new syllable
      if (cur.length) { syls.push(cur.join('')); cur = [] }
      cur.push(c)
    } else if (_TH_CONS(c) && cur.length) {
      // Consonant mid-word: check if it's a new initial
      const prev = chars[i-1]
      const next = chars[i+1]
      const prevWasVow = prev && (isAbove(prev) || prev === '\u0e32' || _TH_LEAD.has(prev))
      const nextIsVow = next && (isAbove(next) || next === '\u0e32' || _TH_LEAD.has(next))
      if (prevWasVow && !nextIsVow && !_TH_STOP.has(c)) {
        // Previous vowel finished → this consonant starts new syllable
        syls.push(cur.join('')); cur = [c]
      } else { cur.push(c) }
    } else { cur.push(c) }
  }
  if (cur.length) syls.push(cur.join(''))
  return syls.length ? syls : [thai]
}

// Correct phonetics for a single vocab word
// ── CONTAINMENT until Step E (thai-canonical-v1) ─────────────────────────────────
// Opening the app must not migrate saved learner vocabulary. The Thai load used to
// copy the bank's gloss, Thai text, phonetic, note and duplicate pointer into saved
// tt-vocab on EVERY load and persist it. That is Step E's job, to be run explicitly
// with a backup, correction log and validation. Until then these writes are paused.
// Learner state (status, SRS, exposure) is still loaded exactly as before.
const THAI_LOAD_LEXICAL_WRITEBACK = false

