  const KNOWN_PARTICLES = ['\u306F','\u304C','\u3092','\u306B','\u3067','\u3068','\u3082','\u306E','\u304B','\u306D','\u3088','\u3060','\u3078','\u304B\u3089','\u307E\u3067']
  const segSurfaces = new Set((pair.segments || []).map(s => s.surface))
