  const enChoice = dailyV693On() && /(何|なに|どれ|どこ)\S{0,6}(る|う|く|む|ぶ|ぐ|す|つ)か/.test(jp) && /\b(what|which|where) (i|you|we) (want|wanna)\b/i.test(en)
